async function responseJson(response) { const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.message || "Something went wrong. Please try again."); return body; }
function readSession() { try { return { token: localStorage.getItem("qs_token") || "", user: JSON.parse(localStorage.getItem("qs_user") || "null") }; } catch { return { token: "", user: null }; } }
function saveSession(data) { localStorage.setItem("qs_token", data.token); localStorage.setItem("qs_user", JSON.stringify(data.user)); }
function clearSession() { localStorage.removeItem("qs_token"); localStorage.removeItem("qs_user"); }

