function EmployeePage({ clerk = null }) {
  const session = readSession(); const [theme, setTheme] = useState(() => localStorage.getItem("qs_theme") || "light"); const [user, setUser] = useState(clerk?.enabled ? null : (session.user?.role === "employee" ? session.user : null)); const [token, setToken] = useState(clerk?.enabled ? "" : (session.user?.role === "employee" ? session.token : "")); const [mode, setMode] = useState("login"); const [form, setForm] = useState({ name: "", phone: "", email: "", password: "" }); const [photoProof, setPhotoProof] = useState(""); const [signatureProof, setSignatureProof] = useState(""); const [pendingId, setPendingId] = useState(""); const [otp, setOtp] = useState(""); const [otpRequested, setOtpRequested] = useState(false); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [tickets, setTickets] = useState([]); const [actionBusy, setActionBusy] = useState(""); const toggleTheme = () => setTheme((current) => { const next = current === "light" ? "dark" : "light"; localStorage.setItem("qs_theme", next); return next; });
  useEffect(() => { if (clerk?.localToken && clerk.localUser) { setUser(clerk.localUser); setToken(clerk.localToken); } }, [clerk?.localToken, clerk?.localUser?.id]);
  async function authenticate(event) { event.preventDefault(); setBusy(true); setError(""); try { const endpoint = mode === "login" ? "/auth/login" : "/employee/register"; const data = await responseJson(await fetch(`${API}${endpoint}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(mode === "login" ? { email: form.email, password: form.password } : { ...form, photoProof, signatureProof }) })); if (mode === "register") { setPendingId(data.pendingId); setOtpRequested(true); setOtp(""); setError(data.devOtp ? `Local development OTP: ${data.devOtp}` : ""); return; } if (data.user.role !== "employee") throw new Error("This account is not registered as an employee."); saveSession(data); setUser(data.user); setToken(data.token); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  async function verifyEmployeeOtp() { setBusy(true); setError(""); try { const data = await responseJson(await fetch(`${API}/employee/verify`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ pendingId, phone: form.phone, otp }) })); saveSession(data); setUser(data.user); setToken(data.token); setOtpRequested(false); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  async function clerkOnboard(event) { event.preventDefault(); setBusy(true); setError(""); try { const clerkToken = await clerk.getToken(); const email = clerk.clerkUser?.primaryEmailAddress?.emailAddress || clerk.clerkUser?.emailAddresses?.[0]?.emailAddress || ""; const data = await responseJson(await fetch(`${API}/employee/clerk-onboard`, { method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${clerkToken}` }, body: JSON.stringify({ name: form.name, phone: form.phone, email, photoProof, signatureProof }) })); saveSession(data); setUser(data.user); setToken(data.token); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  async function loadTickets() { if (!token) return; try { setTickets(await responseJson(await fetch(`${API}/employee/tickets`, { headers: { Authorization: `Bearer ${token}` } }))); } catch (err) { setError(err.message); } }
  useEffect(() => { if (token) loadTickets(); }, [token]);
  function onImage(event, setter, label) { const file = event.target.files?.[0]; if (!file) return; if (!file.type.startsWith("image/")) { setError(`Choose an image file for ${label}.`); return; } if (file.size > 700_000) { setError(`${label} must be smaller than 700 KB.`); return; } const reader = new FileReader(); reader.onload = () => setter(String(reader.result)); reader.readAsDataURL(file); }
  const onPhoto = (event) => onImage(event, setPhotoProof, "photo confirmation");
  async function acceptTicket(ticket) { setActionBusy(ticket._id); try { const updated = await responseJson(await fetch(`${API}/employee/tickets/${ticket._id}/accept`, { method: "PATCH", headers: { Authorization: `Bearer ${token}` } })); setTickets((current) => current.map((item) => item._id === ticket._id ? { ...item, ...updated, status: "assigned" } : item)); } catch (err) { setError(err.message); } finally { setActionBusy(""); } }
  async function logout() { if (!window.confirm("Sign out of the employee dashboard?")) return; if (clerk?.enabled && clerk.signOut) await clerk.signOut(); clearSession(); setUser(null); setToken(""); }
  if (!user && !clerk?.enabled) return <EmployeeFallbackAuth theme={theme} onToggle={toggleTheme} mode={mode} setMode={(value) => { setMode(value); setOtpRequested(false); setError(""); }} form={form} setForm={setForm} photoProof={photoProof} signatureProof={signatureProof} onImage={(event, field, label) => onImage(event, field === "photoProof" ? setPhotoProof : setSignatureProof, label)} otpRequested={otpRequested} otp={otp} setOtp={setOtp} verifyEmployeeOtp={verifyEmployeeOtp} error={error} busy={busy} authenticate={authenticate} />;
  if (clerk?.enabled && !user) {
    return <div className={`portal-shell ${theme === "dark" ? "theme-dark" : ""}`}><PortalHeader title="Professional workspace" theme={theme} onToggle={toggleTheme} user={null} /><section className="portal-auth"><div className="portal-auth-card employee-auth">{!clerk.isSignedIn ? <ClerkAuthPanel mode={mode} onModeChange={setMode} title="Employee access" /> : <><div className="portal-kicker"><UserCheck size={16} /> EMPLOYEE ONBOARDING</div><h1>Complete your profile</h1><p>Upload your profile photo and signature before viewing customer tickets.</p><form onSubmit={clerkOnboard}><label>Full name<input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Your name" /></label><label>Phone number<input required pattern="[0-9]{10}" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value.replace(/\D/g, "").slice(0, 10) })} placeholder="10-digit mobile number" /></label><label>Profile photo<input required type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => onImage(event, setPhotoProof, "profile photo")} /><small className="file-help">Upload a clear profile photo. Maximum 700 KB.</small></label><label>Signature image<input required type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => onImage(event, setSignatureProof, "signature image")} /><small className="file-help">Upload a clear signature image. Maximum 700 KB.</small></label>{error && <div className="form-error">{error}</div>}<button className="primary-btn full" type="submit" disabled={busy || !photoProof || !signatureProof}>{busy ? "Saving profile…" : "Finish employee registration"}</button></form></>}</div></section></div>;
  }
  return <div className={`portal-shell ${theme === "dark" ? "theme-dark" : ""}`}><PortalHeader title="Professional workspace" theme={theme} onToggle={toggleTheme} user={user} onLogout={logout} />{!user ? <section className="portal-auth"><div className="portal-auth-card employee-auth"><div className="portal-kicker"><UserCheck size={16} /> EMPLOYEE ACCESS</div><h1>{mode === "login" ? "Employee sign in" : "Join QuickServe"}</h1><p>{mode === "login" ? "Sign in to view available customer tickets." : "Create an employee account with photo confirmation before accepting work."}</p><form onSubmit={authenticate}>{mode === "register" && <><label>Full name<input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Your name" /></label><label>Phone number<input required pattern="[0-9]{10}" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value.replace(/\D/g, "").slice(0, 10) })} placeholder="10-digit mobile number" /></label><label>Photo confirmation<input required type="file" accept="image/png,image/jpeg,image/webp" onChange={onPhoto} /><small className="file-help">Upload a clear profile or ID photo for confirmation.</small></label></>}<label>Email address<input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} placeholder="you@example.com" /></label><label>Password<input required minLength="8" type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} placeholder="At least 8 characters" /></label>{error && <div className="form-error">{error}</div>}<button className="primary-btn full" type="submit" disabled={busy || (mode === "register" && !photoProof)}>{busy ? "Please wait…" : mode === "login" ? "Sign in" : "Create employee account"}</button></form><button type="button" className="text-button" onClick={() => { setMode(mode === "login" ? "register" : "login"); setError(""); }}>{mode === "login" ? "Need an employee account? Sign up" : "Already registered? Sign in"}</button></div></section> : <main className="portal-main"><div className="portal-heading"><div><div className="eyebrow">EMPLOYEE TICKET QUEUE</div><h1>Customer visits</h1><p>Review the address, call the customer, open the map and confirm the ticket you will take.</p></div><button className="secondary-btn" type="button" onClick={loadTickets}><RefreshCw size={14} /> Refresh</button></div>{error && <div className="form-error">{error}</div>}<div className="portal-list">{tickets.length === 0 ? <div className="empty-state"><ClipboardList size={32} /><h3>No available tickets</h3><p>New confirmed bookings will appear here.</p></div> : tickets.map((ticket) => { const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${ticket.address}, ${ticket.area || ""}`)}`; return <article className="portal-ticket employee-ticket" key={ticket._id}><div className="ticket-main"><div className="ticket-icon"><MapPin /></div><div><strong>{ticket.ticketId || "QuickServe ticket"}</strong><h3>{ticket.items?.map((item) => item.name).join(", ")}</h3><p><UserRound size={13} /> {ticket.customer?.name || "Customer"} · <a href={`tel:${ticket.customer?.phone || ""}`}><Phone size={13} /> {ticket.customer?.phone || "Phone not available"}</a></p><small><MapPin size={13} /> {ticket.address}{ticket.area ? `, ${ticket.area}` : ""}</small><small><CalendarDays size={13} /> {formatDate(ticket.scheduledAt)}</small></div></div><div className="ticket-side"><span className={`status status-${ticket.status}`}>{statusLabel(ticket.status)}</span><a className="map-button" href={mapUrl} target="_blank" rel="noreferrer"><Navigation size={14} /> Open map</a>{ticket.status === "confirmed" ? <button className="primary-btn" type="button" disabled={actionBusy === ticket._id} onClick={() => acceptTicket(ticket)}>{actionBusy === ticket._id ? "Confirming…" : <><CheckCircle2 size={14} /> Confirm ticket</>}</button> : <span className="accepted-label"><CheckCircle2 size={14} /> Assigned to you</span>}</div></article>; })}</div></main>}</div>;
}

export default function App() { if (window.location.pathname === "/admin/employees") return <AdminEmployeesPage />; if (window.location.pathname.startsWith("/admin")) return <AdminPage />; if (window.location.pathname.startsWith("/employee")) return CLERK_ENABLED ? <ClerkEmployeeGate /> : <EmployeePage />; return CLERK_ENABLED ? <ClerkCustomerGate /> : <CustomerApp />; }
